  // desk + crates
  rect(46,156,121,15,'#855c3e');rect(56,171,10,26,'#604637');rect(147,171,10,26,'#604637');rect(68,140,37,16,'#304347');rect(71,143,31,9,'#80a36c');rect(295,149,48,42,'#74563a');rect(300,154,38,31,'#8e6e45');rect(307,161,22,17,'#243534');rect(371,164,50,27,'#65503b');rect(377,169,38,18,'#8c6941');rect(23,163,16,30,'#485956');rect(27,167,8,17,'#9b7952');
