  // character sprite
  const px=state.walkX||278,py=state.walkY||206;rect(px,py+13,18,16,'#202a2d');rect(px+3,py+3,12,12,'#e0b48d');rect(px+1,py,16,6,'#20272a');rect(px+2,py+5,3,3,'#222');rect(px+12,py+5,3,3,'#222');rect(px,py+15,18,9,'#a84843');rect(px+3,py+14,12,3,'#d37466');rect(px+2,py+23,5,6,'#333d39');rect(px+11,py+23,5,6,'#333d39');rect(px+6,py+16,6,2,'#d2d6ae');
  // creature beside player
  const mon=state.team[0]&&creature(state.team[0]);if(mon){rect(px+22,py+17,18,12,'#789a61');rect(px+26,py+11,13,12,'#a0bd79');rect(px+27,py+8,4,8,'#789a61');rect(px+36,py+8,4,8,'#789a61');rect(px+29,py+16,2,2,'#172323');rect(px+37,py+16,2,2,'#172323')}
  // wall sign + pixel lamps
  rect(171,72,65,21,'#18272a');rect(175,76,57,13,'#c8f169');x.fillStyle='#28372b';x.font='bold 8px monospace';x.fillText('ROCKET HQ',179,85);rect(303,43,9,9,'#ffb765');rect(306,46,3,3,'#fff0ae');
  if(state.walkX){x.fillStyle='#d9f38d';x.font='9px monospace';x.fillText('E  TALK',px-2,py-5)}
