function drawMap(){const c=$('#field-canvas');if(!c)return;const x=c.getContext('2d');x.imageSmoothingEnabled=false;const W=600,H=350; x.fillStyle='#263a37';x.fillRect(0,0,W,H);const tile=25;for(let y=0;y<H;y+=tile)for(let a=0;a<W;a+=tile){x.fillStyle=((a/tile+y/tile)%2)?'#31463d':'#2d4139';x.fillRect(a,y,tile,tile);if((a*7+y*3)%11===0){x.fillStyle='#486149';x.fillRect(a+7,y+6,3,3)}}
 x.fillStyle='#777552';x.fillRect(0,153,600,39);x.fillRect(264,0,45,350);x.fillStyle='#b4a779';x.fillRect(0,161,600,22);x.fillRect(273,0,27,350);x.fillStyle='#716c4e';x.fillRect(0,171,600,2);x.fillRect(285,0,2,350);
 const places=[['ROCKET HQ',65,72,'#c65349'],['BRASS GYM',440,77,'#d29d58'],['TIDELINE',443,260,'#679da3'],['MARKET ROW',78,260,'#af7865'],['LEAGUE',494,166,'#9d99bc']];for(const [name,a,b,col] of places){x.fillStyle='#19282b';x.fillRect(a-24,b-20,67,44);x.fillStyle=col;x.fillRect(a-20,b-16,59,32);x.fillStyle='#1b2b2d';x.fillRect(a-16,b-12,51,24);x.fillStyle='#d4d7ae';x.fillRect(a-2,b+6,11,14);x.fillStyle='#e6eac0';x.font='8px monospace';x.fillText(name,a-21,b+37)}
 // player location and pins
 x.fillStyle='#c8f169';x.fillRect(269,159,15,16);x.fillStyle='#29352c';x.fillRect(273,162,7,7);x.fillStyle='#efffae';x.font='bold 8px monospace';x.fillText(state.rank===0?'YOU / HQ':'YOU / '+(state.towns.at(-1)||'HQ'),230,151);
 if(state.gyms.includes('brass')){x.fillStyle='#f9d979';x.fillRect(445,63,8,8)}
}
function fieldTrainer(){
  if(!state.trainers[state.location]){
    const seed=Math.floor(Math.random()*POKEMON.length),species=POKEMON[seed];
    state.trainers[state.location]={name:['Rival Scout','League Courier','Route Ace','Café Battler'][Math.floor(Math.random()*4)],species:species.name,icon:species.icon,hp:30+Math.floor(Math.random()*16),atk:7+Math.floor(Math.random()*5),def:3+Math.floor(Math.random()*4),reward:20+Math.floor(Math.random()*31),defeated:false,stolen:false};
  }
  return state.trainers[state.location];
}
function startMapTrainer(){
  const trainer=fieldTrainer();if(trainer.defeated)return toast('This trainer has already been dealt with.');
  startBattle({kind:'trainer',title:`Kanto Route Trainer · ${trainer.name}`,id:state.location,reward:trainer.reward,enemy:{name:trainer.species,icon:trainer.icon,hp:trainer.hp,atk:trainer.atk,def:trainer.def}});
}
function stealFromTrainer(){
  const trainer=fieldTrainer();if(trainer.stolen)return toast('You already lifted this trainer’s cash.');
  if(trainer.defeated)return toast('There is nothing left to take from this trainer.');
  if(Math.random()<.72){const loot=10+Math.floor(Math.random()*26);state.credits+=loot;trainer.stolen=true;save();render();toast(`Pickpocketed ${loot}¢ from ${trainer.name}.`);}
  else{trainer.stolen=true;save();toast(`${trainer.name} caught your hand! A battle starts.`);startMapTrainer();}
}
function stealNiasBike(){
  if(state.bikeStolen)return toast(`${state.leagueRivalName}’s bike is already stashed at HQ.`);
  state.bikeStolen=true;state.rival=Math.max(state.rival,1);save();render();toast(`Bike stolen. Kanto travel is now free—and ${state.leagueRivalName} is on your trail.`);
}
function startSafariEncounter(){
  if(state.location!=='Safari Zone')return;
  if(state.credits<10)return toast('Safari entry costs 10¢.');
  state.credits-=10;const species=POKEMON[Math.floor(Math.random()*POKEMON.length)];
  const caught=freshCreature(species.id);caught.level=1+Math.floor(Math.random()*8);caught.maxHp+=caught.level*2;caught.hp=caught.maxHp;caught.atk+=Math.floor(caught.level/3);caught.def+=Math.floor(caught.level/4);
  state.caught.push(caught);if(state.team.length<6)state.team.push(caught.id);save();render();toast(`${species.name} captured${state.team.includes(caught.id)?' and added to your crew':' and sent to storage'}!`);
}
function claimSafariBusiness(){
  if(state.safariControl)return toast('Your Safari business is already operating.');
  state.safariControl=true;save();render();toast('Safari Zone claimed. It will add 25¢ to every shift.');
}
function renderField(){
  const town=KANTO_TOWNS.find(item=>item.name===state.location)||KANTO_TOWNS[0];
  const gymState=town.gym===null?'':state.league>town.gym?'GYM CLEARED':state.league===town.gym?'CHALLENGE READY':`BADGE ${town.gym} REQUIRED`;
  let feature='';
  if(town.gym!==null){const stage=LEAGUE_GYMS[town.gym];feature=`<div class="town-feature"><div class="panel-head"><h2>${stage.name}</h2><span>${gymState}</span></div><p>${stage.leader} · ${stage.theme}. Each Kanto Gym is physically located in its home town; defeat them in badge order.</p><button class="btn" data-town-gym="${town.gym}" ${state.league!==town.gym?'disabled':''}>${state.league>town.gym?'BADGE EARNED':state.league===town.gym?'CHALLENGE GYM →':'GYM LOCKED'}</button></div>`}
  else if(town.name==='Safari Zone')feature=`<div class="town-feature safari-feature"><div class="panel-head"><h2>Safari Zone Reserve</h2><span>GRUNT ACCESS</span></div><p>Explore the reserve, encounter one of the 151 catalog species, and capture it for your crew. Captures beyond your six active slots stay in storage.</p><div class="btn-row"><button class="btn" id="safari-explore">EXPLORE · 10¢</button><button class="btn secondary" id="safari-control">${state.safariControl?'BUSINESS OWNED':'CLAIM SAFARI BUSINESS'}</button></div><div class="notice" style="margin-top:10px">${state.safariControl?'Your Safari business earns 25¢ whenever you work a shift.':'Claim the reserve as a Rocket front to generate income from future shifts.'}</div></div>`;
  else if(town.name==='Indigo Plateau')feature=`<div class="town-feature"><div class="panel-head"><h2>Indigo Plateau</h2><span>${state.league<8?'EARN 8 BADGES FIRST':state.league<11?'VICTORY ROAD':state.league<15?'ELITE FOUR':state.league===15?'CHAMPION':'TITLE HOLDER'}</span></div><p>${state.league<8?'The League road is sealed until all eight Kanto Gym badges are earned.':state.league<11?'Three stages of Victory Road stand between the badges and the Elite Four.':'The League challenge continues here, from Victory Road through title defenses.'}</p><button class="btn" id="plateau-challenge" ${state.league<8?'disabled':''}>${state.league<8?'ROAD SEALED':'CONTINUE LEAGUE CHALLENGE →'}</button></div>`;
  else feature=`<div class="town-feature"><div class="panel-head"><h2>${town.name} Field Office</h2><span>ROCKET ROUTE</span></div><p>Travel routes are open across Kanto. Visit any town to challenge its Gym, meet local contacts, or continue the League circuit.</p>${town.name==='Cerulean City'&&!state.bikeStolen?`<div class="notice"><b>Nia Vale’s bike:</b> Nia left her new bike unattended near the canal while she questions a League courier. Taking it will make future travel free—and put her on your trail.</div><button class="btn secondary" style="margin-top:10px" id="steal-bike">TAKE NIA’S BIKE</button>`:state.bikeStolen&&town.name==='Cerulean City'?'<div class="notice">Nia’s stolen bike is stashed at HQ. She knows the syndicate took it.</div>':''}</div>`;
  const trainer=fieldTrainer();
  const trainerPanel=`<div class="town-feature trainer-feature"><div class="panel-head"><h2>${trainer.name}</h2><span>${trainer.defeated?'ROUTE CLEARED':'LOCAL TRAINER'}</span></div><p>${trainer.defeated?'This route is quiet for now.':'A roaming trainer and '+trainer.species+' are nearby. Challenge them for '+trainer.reward+'¢ or try a quick pickpocket.'}</p><div class="btn-row"><button class="btn secondary" id="map-trainer" ${trainer.defeated?'disabled':''}>${trainer.defeated?'TRAINER DEFEATED':'CHALLENGE TRAINER'}</button><button class="btn ghost" id="steal-trainer" ${trainer.defeated||trainer.stolen?'disabled':''}>${trainer.stolen?'POCKET PICKED':'STEAL FROM TRAINER'}</button></div></div>`;
  root.innerHTML=pageHead('KANTO ROUTES / FIELD OPERATIONS','Kanto Travel','Travel between all ten Kanto destinations. Every Gym can be challenged from its home town.','LOCATION: '+town.name.toUpperCase())+`<div class="kanto-layout"><section class="panel travel-panel"><div class="panel-head"><h2>Destination board</h2><span>${state.bikeStolen?'BIKE ROUTES OPEN':'ROUTE NETWORK'}</span></div><div class="town-grid">${KANTO_TOWNS.map((item,index)=>`<button class="town-button ${item.name===town.name?'selected':''}" data-travel="${item.name}"><span class="town-number">${String(index+1).padStart(2,'0')}</span><strong>${item.name}</strong><small>${item.gym===null?(item.name==='Safari Zone'?'WILDLIFE RESERVE':item.name==='Indigo Plateau'?'LEAGUE GATE':'ROUTE STOP'):`GYM ${item.gym+1} · ${LEAGUE_GYMS[item.gym].leader}`}</small></button>`).join('')}</div></section><section class="panel town-detail"><div class="panel-head"><h2>Now visiting: ${town.name}</h2><span>${town.gym!==null?`GYM ${town.gym+1}`:town.name==='Safari Zone'?'SAFARI':town.name==='Indigo Plateau'?'LEAGUE':''}</span></div>${feature}</section></div><div class="panel field-contracts"><div class="panel-head"><h2>Route encounter</h2><span>ROAMING TRAINER</span></div>${trainerPanel}</div><div class="panel field-contracts"><div class="panel-head"><h2>Rocket side operations</h2><span>CAMPAIGN CONTRACTS</span></div><div class="op-list">${missionCard('dock','Dockside shake-down','Stop a League courier and claim a creature from the old pier.','LOW','35¢ + capture')}${missionCard('brass','Brass Gym takeover','Challenge foreman Ivo. Win his badge to control Foundry Ward.','MED','Badge + 80¢')}${missionCard('tideline','Tideline town push','Secure the harbor and recruit its waterway crew.','HIGH','Town + 120¢')}${missionCard('market','Market Row takeover','Make the night market pay protection.','HIGH','Town + 140¢')}${missionCard('skyline','Skyline Gym takeover','Challenge Nia’s old rival, the electric-type gym boss.','HIGH','Badge + 150¢')}${missionCard('hilltown','Hilltown control','Bring the uphill farms under syndicate protection.','HIGH','Town + 180¢')}</div><div class="notice" style="margin-top:12px"><b>Intel:</b> ${state.rival<3?`Nia Vale's trail is heating up. ${3-state.rival} story beat${3-state.rival===1?'':'s'} remain.`:'Your rival has reached the League.'}</div></div>`;
  root.querySelectorAll('[data-travel]').forEach(button=>button.onclick=()=>{state.location=button.dataset.travel;save();render()});
  root.querySelectorAll('[data-mission]').forEach(button=>button.onclick=()=>startMission(button.dataset.mission));
  root.querySelector('[data-town-gym]')?.addEventListener('click',()=>startLeagueMatch());
  $('#plateau-challenge')?.addEventListener('click',()=>startLeagueMatch());
  $('#steal-bike')?.addEventListener('click',stealNiasBike);
  $('#safari-explore')?.addEventListener('click',startSafariEncounter);
  $('#safari-control')?.addEventListener('click',claimSafariBusiness);
  $('#map-trainer')?.addEventListener('click',startMapTrainer);
  $('#steal-trainer')?.addEventListener('click',stealFromTrainer);
}
