function workShift(){const base=20+state.rank*5,safari=state.safariControl?25:0,total=base+safari;state.credits+=total;state.morale=Math.min(100,state.morale+5);state.day++;state.lastSpin='Shift complete. +'+total+'¢'+(safari?' (includes Safari income)':'');save();render();toast(`Shift complete. +${total}¢${safari?' including Safari business income.':'.'}`)}
function spin(){if(state.credits<state.bet){toast('Not enough credits to bet that much.');return}state.credits-=state.bet;const symbols=['🍒','◆','7','★','●','⚡'];const weights=[28,24,16,12,10+state.upgrades.luck*2,10+state.upgrades.luck*3];const pick=()=>{let n=Math.random()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<weights.length;i++){n-=weights[i];if(n<=0)return symbols[i]}return symbols[0]};let r=[pick(),pick(),pick()];for(let i=0;i<3;i++)$('#reel-'+i).textContent=r[i];let win=0;if(r[0]===r[1]&&r[1]===r[2]){const mult={'🍒':5,'◆':7,'7':10,'★':14,'●':18,'⚡':25};win=state.bet*mult[r[0]]+state.upgrades.slots*10;if(r[0]==='⚡')win+=Math.floor(state.credits*.4)}else if(r.filter(a=>a==='🍒').length>=2)win=state.bet*2;else if(new Set(r).size===2)win=state.bet;
 state.credits+=win;state.lastSpin=win?`WIN! ${r.join(' ')}  +${win}¢`:`${r.join(' ')}  NO PAYOUT`;if(win){state.morale=Math.min(100,state.morale+Math.min(12,Math.ceil(win/20)));toast(`You won ${win} credits!`)}else toast('No payout this time.');save();$('#slot-result').textContent=state.lastSpin;$('#credit-label').textContent=String(state.credits).padStart(3,'0');root.querySelectorAll('[data-buy]').forEach(b=>b.disabled=state.credits<Number(b.textContent.replace('BUY','')))}
function buyPrize(id){const costs={fieldkit:80,pockets:120,training:100,luck:140,slots:180};const cost=costs[id];if(state.credits<cost)return toast('Not enough credits.');if(state.upgrades[id]>0)return toast('Already purchased.');if(id==='pockets'&&state.caught.length>=6)return toast('Your crew is full.');state.credits-=cost;if(id==='fieldkit'){state.upgrades.fieldkit=1;state.caught.forEach(c=>{c.maxHp+=5;c.hp+=5})}else if(id==='pockets'){state.upgrades.pockets=1;const c=CREATURES.find(x=>!state.caught.some(y=>y.id===x.id));if(c){state.caught.push(freshCreature(c.id));state.team.push(c.id)}}else if(id==='training'){state.upgrades.training=1;state.caught.forEach(c=>c.atk+=2)}else state.upgrades[id]=1;state.lastSpin=`${id.toUpperCase()} acquired.`;save();render();toast('Permanent upgrade acquired!')}
